from typing import Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def minDiffInBST(self, root: Optional[TreeNode]) -> int:
        self.prev = None
        self.ans = float('inf')

        def inorder(node: Optional[TreeNode]) -> None:
            if not node:
                return
            inorder(node.left)
            if self.prev is not None:
                self.ans = min(self.ans, node.val - self.prev)
            self.prev = node.val
            inorder(node.right)

        inorder(root)
        return int(self.ans)

class Solution {
    int prevVal = -1;
    int ans = INT_MAX;
    void inorder(TreeNode* node) {
        if (!node) return;
        inorder(node->left);
        if (prevVal != -1) ans = min(ans, node->val - prevVal);
        prevVal = node->val;
        inorder(node->right);
    }
public:
    int minDiffInBST(TreeNode* root) {
        inorder(root);
        return ans;
    }
};

class Solution {
    private Integer prev = null;
    private int ans = Integer.MAX_VALUE;
    public int minDiffInBST(TreeNode root) {
        inorder(root);
        return ans;
    }
    private void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        if (prev != null) ans = Math.min(ans, node.val - prev);
        prev = node.val;
        inorder(node.right);
    }
}

var minDiffInBST = function(root) {
    let prev = null;
    let ans = Infinity;
    function inorder(node) {
        if (!node) return;
        inorder(node.left);
        if (prev !== null) ans = Math.min(ans, node.val - prev);
        prev = node.val;
        inorder(node.right);
    }
    inorder(root);
    return ans;
};
